script:
HIGH = 'High'

if doc.get('custom_risk_rating') == HIGH and not doc.get('custom_risk_review_date'):
    frappe.throw('Risk Review Date is required when Vendor Risk Rating is High.')

MIN_YEARS = 2
MIN_MONTHS = 3

state = doc.get('workflow_state') or ''
if state in ('Under Review', 'Approved'):
    est = doc.get('custom_establishment_date')
    if not est:
        frappe.throw('Establishment Date is required before review/approval.')
    today = frappe.utils.getdate(frappe.utils.today())
    years = (today - frappe.utils.getdate(est)).days / 365.0
    if years < MIN_YEARS:
        frappe.throw('Supplier must be in existence for at least {0} years.'.format(MIN_YEARS))

    months = frappe.utils.cint(doc.get('custom_product_availability_months') or 0)
    if months < MIN_MONTHS:
        frappe.throw('Product must be available in the civil market for at least {0} months.'.format(MIN_MONTHS))

    if doc.get('custom_is_sole_marketer') != 'Yes':
        frappe.throw('Supplier must be the sole marketer (set Is Sole Marketer to "Yes").')

MIN_TAX_ID_LEN = 6
MIN_BANK_ACCT_NO_LEN = 6
MIN_IBAN_LEN = 15
MAX_IBAN_LEN = 34

# Basic email check
email = doc.get('email_id')
if email:
    ok = frappe.utils.validate_email_address(email, False)
    if not ok:
        frappe.throw('Email ID is not valid.')

# Basic website URL check
website = doc.get('website')
if website:
    ok = frappe.utils.validate_url(website, False)
    if not ok:
        frappe.throw('Website URL is not valid.')

# Basic phone check (primary mobile if available)
mobile = doc.get('mobile_no')
if mobile:
    ok = frappe.utils.validate_phone_number(mobile, False)
    if not ok:
        frappe.throw('Mobile number is not valid.')

# Basic UPI check (very light since no regex allowed)
upi = doc.get('custom_upi_id')
if upi:
    if ' ' in upi or '@' not in upi or len(upi) < 5:
        frappe.throw('UPI ID seems invalid. It should contain "@" and no spaces.')

# Tax ID presence/format (if provided)
tax_id = doc.get('tax_id')
if tax_id:
    if len(tax_id) < MIN_TAX_ID_LEN or not tax_id.replace(' ', '').isalnum():
        frappe.throw('Tax ID format looks invalid (min length and alphanumeric expected).')

# Default Bank Account validations (if linked)
def_bank = doc.get('default_bank_account')
if def_bank:
    values = frappe.db.get_value('Bank Account', def_bank, ['iban', 'bank_account_no'])
    iban_val = None
    bank_no_val = None
    if values:
        if isinstance(values, tuple):
            iban_val, bank_no_val = values[0], values[1]
        else:
            iban_val = values
    if not (iban_val or bank_no_val):
        frappe.throw('Default Bank Account must have either IBAN or Bank Account No.')
    if iban_val:
        if len(iban_val) < MIN_IBAN_LEN or len(iban_val) > MAX_IBAN_LEN:
            frappe.throw('IBAN length must be between {0} and {1} characters.'.format(MIN_IBAN_LEN, MAX_IBAN_LEN))
    if bank_no_val:
        clean_no = bank_no_val.replace(' ', '')
        if len(clean_no) < MIN_BANK_ACCT_NO_LEN or not clean_no.isdigit():
            frappe.throw('Bank Account No must be numeric and at least {0} digits.'.format(MIN_BANK_ACCT_NO_LEN))

if doc.get('custom_document_type') == 'C-Form':
    if not doc.get('custom_c_form_number'):
        frappe.throw('C-Form Number is required for documents marked as C-Form.')
    if not doc.get('custom_document_file'):
        frappe.throw('Please attach the C-Form file in Document File for C-Form submissions.')
    if not doc.get('custom_c_form_received_date'):
        doc.custom_c_form_received_date = frappe.utils.today()
else:
    pass

if not doc.get('valid_from'):
    frappe.throw('Valid From (valid_from) is mandatory.')
if not doc.get('valid_to'):
    frappe.throw('Valid To (valid_to) is mandatory.')
if doc.get('valid_from') and doc.get('valid_to'):
    if frappe.utils.getdate(doc.valid_to) < frappe.utils.getdate(doc.valid_from):
        frappe.throw('Valid To (valid_to) must be the same or after Valid From (valid_from).')
if not doc.get('scheme_details') or not (doc.scheme_details or '').strip():
    frappe.throw('Scheme Details (scheme_details) is mandatory.')
if doc.get('custom_benefit_value') in (None, ''):
    frappe.throw('Benefit value (custom_benefit_value) is mandatory.')

for row in (doc.items or []):
    if not (row.generic_code or row.item):
        frappe.throw('Each product line must have either a Generic Code or an Item.')

SEEN_GENERIC_CODES = []
for row in (doc.items or []):
    code = row.generic_code
    if code:
        if code in SEEN_GENERIC_CODES:
            frappe.throw("Duplicate generic code '%s' in a single Supplier Product Registration is not allowed." % code)
        SEEN_GENERIC_CODES.append(code)

if doc.get('valid_from') and doc.get('valid_to'):
    if frappe.utils.getdate(doc.valid_to) < frappe.utils.getdate(doc.valid_from):
        frappe.throw('"Valid To" cannot be earlier than "Valid From"')
